import { resolve as resolveContract } from "../../../extensions/contracts.js";
export async function compileMDX(content, options) {
    const processor = resolveContract("ContentProcessor");
    const compiled = await processor.compileMdx({
        projectDir: options.projectDir,
        content,
        mode: options.mode,
        target: "server",
    });
    return { code: compiled.compiledCode, imports: extractImports(compiled.compiledCode) };
}
function extractImports(code) {
    const imports = [];
    const importRegex = /import\s+(?:(?:\{[^}]*\}|\*\s+as\s+\w+|\w+)\s+from\s+)?['"]([^'"]+)['"]/g;
    for (const match of code.matchAll(importRegex)) {
        const specifier = match[1];
        if (specifier)
            imports.push(specifier);
    }
    return imports;
}
